"""Source-reviewed language structures: exact answers, contextual analysis, competing readings."""
import html
E=lambda s:html.escape(str(s),quote=True)
LANGUAGE_SOURCES={
 'fpjd_context2026':('公式調査票と再照合｜設問の文脈','国立国語研究所「全国方言分布調査（FPJD）」調査項目一覧・質問文および公開回答。','https://www2.ninjal.ac.jp/hogen/dp/fpjd/fpjd_index.html','2026年11月13日に公式ZIPを再取得。公開ページの更新は2025年10月14日、回答ファイル名の版日は2025年10月7日。磐田市1地点の211設問・287回答について項目名・語形・原注を照合し一致。各節の文脈は調査票の要約。2010–2015年の全国調査とファイル公開年を区別し、地点の非公開話者属性や磐田全市の使用率を推測しません。'),
 'uda2017':('談話研究｜移住と言語使用','宇田萌美（2017）「母方言・移住先方言・標準語のスタイルシフトの実態」『阪大社会言語学研究ノート』15、1–21頁。','https://doi.org/10.18910/67209','対象・方法5–8頁、分析とまとめ17–20頁を公開本文で確認。福山から浜松へ移住した1人を中心とする8つの二者談話。各20分の文字化資料を用いた個人事例で、浜松市民全体の割合ではありません。本文・表の画像や会話全文は転載しません。'),
 'iinisuru2023':('発表原稿｜複数の意味と使用意識','峯尾海成・谷口ジョイ（2023）「静岡方言『いいにする』の多義性およびその使用・理解」『日本方言研究会第116回研究発表会発表原稿集』9–16頁。','https://doi.org/10.60263/hougen.116.0_9','10頁の調査方法、11頁の4用法・表1、15頁の解釈と限界を原PDF画像で確認。予備聞き取り70名とウェブ回答1,770名を区別。県西部513名・中部848名・東部409名は回答者の内訳で、無作為の人口標本ではありません。学会発表原稿を査読論文と表示せず、図表・原稿PDFは転載しません。'),
}

def make_language_notes(table,responses,cite):
 notes=[]
 F=cite('fpjd_context2026','FPJD公式調査票・再照合した原回答')
 def add(slug,field,title,deck,finding,questions,parts,exercise,answer,group='language',sources=None,extra=''):
  headings,paragraphs=parts
  ids=['question','evidence','analysis','alternatives','method']
  body=''
  for i,(sid,heading,ps) in enumerate(zip(ids,headings,paragraphs)):
   body+=f'<section id="{sid}"><h2>{E(heading)}</h2>'
   if i==1 and questions:body+=responses(*questions)
   if i==1:body+=extra
   body+=''.join('<p>'+p+'</p>' for p in ps)
   if i==1 and questions:body+='<p class="research-small">'+F+'。上表は選んだ設問の全回答です。〈 〉などの原注を含め、共通語への置換で統一していません。</p>'
   if i==4:body+=f'<aside class="research-exercise"><p class="eyebrow">READ &amp; THINK</p><h3>{E(exercise)}</h3><details><summary>考え方を読む</summary><p>{answer}</p></details></aside>'
   body+='</section>'
  notes.append(dict(slug=slug,field=field,title=title,deck=deck,finding=finding,body=body,group=group,sources=sources or ['fpjd','fpjd_context2026','notes'],questions=list(questions)))

